begin;
do $$
declare e uuid:=gen_random_uuid(); w uuid:=gen_random_uuid(); x uuid:=gen_random_uuid(); ad uuid:=gen_random_uuid(); j uuid; n uuid; note uuid:=gen_random_uuid(); total integer; before_count integer;
begin
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into auth.users(id,email,raw_user_meta_data) values(e,e||'@alerts.invalid','{"account_type":"employer"}'),(w,w||'@alerts.invalid','{}'),(x,x||'@alerts.invalid','{}'),(ad,ad||'@alerts.invalid','{}');
 update public.profiles set role='admin' where id=ad;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);set local role authenticated;
 insert into public.notification_preferences(user_id,email_kinds,job_alerts,categories,keywords,location) values(w,array['job_alert','invitation','announcement'],true,array['Development'],array['editing'],'Kathmandu');
 begin insert into public.notification_preferences(user_id) values(x);raise exception 'Foreign preferences accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);
 if exists(select 1 from public.notification_preferences where user_id=w) then raise exception 'Preferences leaked';end if;
 begin perform public.send_admin_notice(note,'both','Test notice','This is only a rollback test.',0);raise exception 'Non-admin sent notice';exception when raise_exception then if sqlerrm<>'Admin only' then raise;end if;end;
 begin perform public.claim_notification_emails(1);raise exception 'Queue exposed';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 insert into public.jobs(employer_id,title,description,category,location,status) values(e,'Test development role','This is a temporary rollback-only development role.','Development','Kathmandu','published') returning id into j;
 if (select count(*) from public.notifications where recipient_id=w and href='/jobs/'||j)<>1 then raise exception 'Matching job alert missing';end if;
 if exists(select 1 from public.notifications where recipient_id=x and href='/jobs/'||j) then raise exception 'Unsubscribed worker alerted';end if;
 if (select count(*) from public.email_outbox where recipient_id=w and kind='job_alert')<>1 then raise exception 'Matching email missing';end if;
 update public.jobs set status='closed' where id=j;update public.jobs set status='published' where id=j;
 if (select count(*) from public.notifications where recipient_id=w and href='/jobs/'||j)<>1 then raise exception 'Duplicate job alert';end if;
 insert into public.notifications(recipient_id,kind,title,href) values(w,'hiring','A previous hirer invited you to a new job','/dashboard/invitations') returning id into n;
 if not exists(select 1 from public.email_outbox where notification_id=n and kind='invitation') then raise exception 'Invitation not queued';end if;
 insert into public.notifications(recipient_id,kind,title,href) values(w,'message','Message email is off','/dashboard/messages') returning id into n;
 if exists(select 1 from public.email_outbox where notification_id=n) then raise exception 'Disabled type queued';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',x,'role','authenticated')::text,true);set local role authenticated;
 update public.notifications set read_at=now() where id=n;
 reset role;if (select read_at from public.notifications where id=n) is not null then raise exception 'Foreign notification marked read';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',ad,'role','authenticated')::text,true);set local role authenticated;
 select count(*) into total from public.profiles where role='freelancer';
 perform public.send_admin_notice(note,'freelancer','Test notice','This is a rollback-only notice.',total);
 perform public.send_admin_notice(note,'freelancer','Test notice','This is a rollback-only notice.',total);
 if (select count(*) from public.notice_recipients where notice_id=note)<>total then raise exception 'Audience count mismatch';end if;
 if exists(select 1 from public.notice_recipients where notice_id=note and user_id=e) then raise exception 'Employer received worker notice';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',e,'role','authenticated')::text,true);
 if exists(select 1 from public.admin_notices where id=note) then raise exception 'Notice leaked outside audience';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',w,'role','authenticated')::text,true);
 if not exists(select 1 from public.admin_notices where id=note) then raise exception 'Recipient cannot read notice';end if;
 update public.notifications set read_at=now() where recipient_id=w;
 if exists(select 1 from public.notifications where recipient_id=w and read_at is null) then raise exception 'Mark read failed';end if;
 reset role;perform set_config('request.jwt.claims','{}',true);
end $$;
select 'Email preferences, category matches, deduplication, notice audience and private access checks passed; all changes rolled back' as result;

rollback;
